use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; use std :: path :: Path ; use super :: * ; impl GitmodulesData { pub fn new () -> Self { Self { submodules : HashMap :: new () , total_count : 0 , git_config : None , } } # [doc = " Parse .gitmodules file with annotation support"] pub fn parse_file < P : AsRef < Path > > (path : P) -> anyhow :: Result < Self > { let content = std :: fs :: read_to_string (path . as_ref ()) ? ; Self :: parse (& content) } # [doc = " Parse .gitmodules content string"] pub fn parse (content : & str) -> anyhow :: Result < Self > { let mut data = GitmodulesData :: new () ; let mut current_name : Option < String > = None ; let mut current_path : Option < String > = None ; let mut current_url : Option < String > = None ; let mut annotations = Vec :: new () ; let mut in_annotations = false ; for line in content . lines () { let trimmed = line . trim () ; if trimmed . is_empty () { if let (Some (name) , Some (path) , Some (url)) = (current_name . take () , current_path . take () , current_url . take ()) { data . submodules . insert (name . clone () , SubmoduleEntry { path , url , branch : None , annotations : annotations . clone () , tracked_attributes : HashMap :: new () , }) ; annotations . clear () ; } in_annotations = false ; continue ; } if trimmed . starts_with ("[submodule \"") { let name = trimmed . trim_start_matches ("[submodule \"") . trim_end_matches ("\"]") ; current_name = Some (name . to_string ()) ; in_annotations = false ; } else if trimmed . starts_with ("path = ") { current_path = Some (trimmed . trim_start_matches ("path = ") . to_string ()) ; } else if trimmed . starts_with ("url = ") { current_url = Some (trimmed . trim_start_matches ("url = ") . to_string ()) ; } else if trimmed . starts_with ("branch = ") { if let Some (ref mut entry) = data . submodules . get_mut (current_name . as_ref () . unwrap ()) { entry . branch = Some (trimmed . trim_start_matches ("branch = ") . to_string ()) ; } } else if trimmed . starts_with ("# gemini-annotations:") { in_annotations = true ; } else if trimmed . starts_with ("#   ") && in_annotations { let annotation = trimmed . trim_start_matches ("#   ") ; if let Some ((key , value)) = annotation . split_once (": ") { annotations . push (Annotation { key : key . to_string () , value : value . to_string () , }) ; } } } if let (Some (name) , Some (path) , Some (url)) = (current_name , current_path , current_url) { data . submodules . insert (name , SubmoduleEntry { path , url , branch : None , annotations , tracked_attributes : HashMap :: new () , }) ; } data . total_count = data . submodules . len () ; Ok (data) } # [doc = " Parse .git/config and attach to data"] pub fn with_git_config (mut self , config_path : & Path) -> anyhow :: Result < Self > { self . git_config = Some (GitConfig :: parse_file (config_path) ?) ; Ok (self) } # [doc = " Find submodules by annotation key/value"] pub fn find_by_annotation (& self , key : & str , value : & str) -> Vec < & SubmoduleEntry > { self . submodules . values () . filter (| entry | { entry . annotations . iter () . any (| a | a . key == key && a . value == value) }) . collect () } # [doc = " Set tracked attribute on submodule"] pub fn set_attribute (& mut self , name : & str , key : & str , value : & str) -> bool { if let Some (entry) = self . submodules . get_mut (name) { entry . tracked_attributes . insert (key . to_string () , value . to_string ()) ; true } else { false } } # [doc = " Get all submodules with a specific attribute"] pub fn find_by_attribute (& self , key : & str) -> Vec < & SubmoduleEntry > { self . submodules . values () . filter (| entry | entry . tracked_attributes . contains_key (key)) . collect () } }